# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">«ATATÜRK VE ÇİFTLİK» DİNLEME/İZLEME METNİ ÇÖZÜMLEMESİ</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Dinleme Stratejileri ve Metin Özeti</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Dinleme Öncesi: Başlık ve görsellerden</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11.5" fill="#1e3a8a">hareketle içeriği tahmin etme, amaç belirleme.</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Dinleme Sırası: Not alarak ve empati kurarak</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11.5" fill="#1e3a8a">dinleme; hikâye unsurlarını ve bölümleri bulma.</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Dinleme Sonrası: Yüzey ve derin anlamı</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11.5" fill="#1e3a8a">belirleme, söz varlığını bağlamdan tahmin etme.</text>\n  <text x="180" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Bölümler: Serim (Giriş) · Düğüm (Gelişme) · Çözüm</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Atatürk Orman Çiftliği ve Kişilik Özellikleri</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Çorak ve bataklık araziyi bilimsel yöntemlerle</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11.5" fill="#14532d">yeşerterek modern bir tarım merkezine dönüştürdü.</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11.5" fill="#14532d">• Doğa ve ağaç sevgisi, kararlılık, ileri görüşlülük,</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11.5" fill="#14532d">çalışkanlık ve milletine hizmet bilinci öne çıkar.</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11.5" fill="#14532d">• Çiftlik arazilerini Türk milletine (Hazineye)</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11.5" fill="#14532d">bağışlayarak vatanseverlik örneği sergiledi.</text>\n  <text x="520" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Modern tarım, ağaçlandırma ve üretim seferberliği</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZ VARLIĞI, SÖZ SANATLARI VE BAĞLANTI İFADELERİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Sözcükte Anlam İlişkileri</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• Gerçek Anlam: Akla gelen ilk</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#78350f">temel anlam (toprağı kazmak).</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11.5" fill="#78350f">• Mecaz Anlam: Gerçek anlamdan</text>\n  <text x="125" y="162" text-anchor="middle" font-size="11.5" fill="#78350f">uzaklaşmış anlam (yeşeren umut).</text>\n  <text x="125" y="188" text-anchor="middle" font-size="11.5" fill="#78350f">• Eş / Zıt / Eş Sesli sözcükler</text>\n  <text x="125" y="206" text-anchor="middle" font-size="11.5" fill="#78350f">ve deyimler (el birliği etmek).</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Söz Sanatları (T.O.5.19)</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#831843">• Benzetme (Teşbih): Zayıf olanı</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#831843">güçlü olana «gibi, kadar» ile</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11.5" fill="#831843">benzetme (Cennet gibi vatan).</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" fill="#831843">• Kişileştirme (Teşhis): İnsana</text>\n  <text x="350" y="182" text-anchor="middle" font-size="11.5" fill="#831843">ait özellikleri doğadaki varlıklara</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11.5" fill="#831843">verme (Gülümseyen fidanlar).</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Bağlantı İfadeleri (T.Y.5.15)</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11.5" fill="#581c87">• Zıtlık / Geçiş: ama, fakat, lakin,</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11.5" fill="#581c87">ancak, buna rağmen, oysa.</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11.5" fill="#581c87">• Neden-Sonuç: çünkü, bu yüzden,</text>\n  <text x="575" y="162" text-anchor="middle" font-size="11.5" fill="#581c87">böylece, dolayısıyla, bu nedenle.</text>\n  <text x="575" y="188" text-anchor="middle" font-size="11.5" fill="#581c87">• Özetleme: kısacası, özetle,</text>\n  <text x="575" y="206" text-anchor="middle" font-size="11.5" fill="#581c87">sonuç olarak, açıkçası.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. TEMA SONU ÖZETİ: YAZIM, NOKTALAMA VE METİN YAPISI</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Yazım Kuralları ve Noktalama (T.Y.5.16)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#155e75">• Kişi adlarından önce ve sonra gelen unvan,</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11.5" fill="#155e75">saygı ve rütbe sözleri büyük harfle başlar:</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#164e63">Gazi Mustafa Kemal Paşa, Çavuş Mehmet.</text>\n  <text x="180" y="162" text-anchor="middle" font-size="11.5" fill="#155e75">• Millî ve dinî bayramlar ile tarihî olaylar</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11.5" fill="#155e75">büyük harfle başlar: Cumhuriyet Bayramı,</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#164e63">Kurtuluş Savaşı, Çanakkale Zaferi.</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#334155">Kurum adlarına gelen ekler kesmeyle ayrılmaz.</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bilgilendirici ve Öyküleyici Metin Yapısı</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Öyküleyici Metin: Olay örgüsü, şahıs/varlık</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11.5" fill="#1e3a8a">kadrosu, mekân ve zaman unsurlarından oluşur</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">(Bölümleri: Serim - Düğüm - Çözüm).</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Bilgilendirici Metin: Okuyucuya bilgi vermek</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11.5" fill="#1e3a8a">ve bir düşünceyi açıklamak için yazılır</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">(Bölümleri: Giriş - Gelişme - Sonuç).</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#334155">Şiirde dörtlük, dize, kafiye, redif ve ahenk aranır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
